<script setup>
import { onMounted, ref } from 'vue'
import { backups, downloadBackup } from '../services/backups.js'
const props = defineProps({ session: { type: Object, required: true } })
const data = ref(null), busy = ref(false), error = ref(''), notice = ref(''), requestKey = ref('')
const days = ['Понеділок','Вівторок','Середа','Четвер','П’ятниця','Субота','Неділя']
const states = { QUEUED: 'Очікує запуску', RUNNING: 'Створюється / перевіряється', SUCCESS: 'Збережено', FAILED: 'Не створено', TRASHED: 'У кошику Google Диска', MISSING: 'Файл відсутній' }
const storage = { NOT_CONFIGURED: 'Ще не підключено', READY: 'Доступ перевірено', ERROR: 'Потрібна перевірка' }
function date(v) { if (!v) return '—'; const raw = String(v).replace(' ', 'T'); const d = new Date(/[zZ]|[+-]\d\d:\d\d$/.test(raw) ? raw : raw+'Z'); return Number.isNaN(d.getTime()) ? v : d.toLocaleString('uk-UA', { timeZone: 'Europe/Kyiv' }) }
async function operation(fn) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function load() { await operation(async () => { data.value = await backups(props.session.token) }) }
async function save() { await operation(async () => { const s=data.value.settings; data.value = await backups(props.session.token, '', { enabled: Boolean(s.enabled), frequency:s.frequency, weekday:Number(s.weekday), time:s.time, keepCount:Number(s.keepCount), revision:s.revision }, 'PUT'); notice.value='Налаштування збережено.' }) }
async function run() { await operation(async () => { if (!requestKey.value) requestKey.value=crypto.randomUUID(); const result=await backups(props.session.token, '/run', { requestKey:requestKey.value }, 'POST'); requestKey.value=''; notice.value=result.invoked ? 'Запуск запитано. Оновіть історію за кілька хвилин.' : 'Запит збережено. Його підхопить планувальник; якщо запуску немає понад 15 хвилин, перевірте Cloud Scheduler.'; data.value=await backups(props.session.token) }) }
async function download(row) { await operation(() => downloadBackup(props.session.token, row)) }
onMounted(load)
</script>
<template><section class="backup"><header><div><h2>Резервне копіювання</h2><p>Повна копія бази MySQL на Google Диск.</p></div><button :disabled="busy" @click="load">Оновити</button></header><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><template v-if="data"><article class="panel"><strong>{{ storage[data.settings.storageStatus] || data.settings.storageStatus }}</strong><p>Остання перевірка: {{ date(data.settings.checkedAt) }}</p><p v-if="data.settings.storageMessage">{{ data.settings.storageMessage }}</p><details><summary>Як підключити Google Диск</summary><p>Адміністратор один раз запускає connect_drive.py на своєму комп’ютері, входить у Google та дозволяє створення копій. Скрипт створить папку «Baget — резервні копії». Дозвіл зберігається в Google Secret Manager за інструкцією з пакета оновлення.</p><p>Після налаштування Cloud Run Job і Cloud Scheduler натисніть «Створити копію зараз». Статус доступу з’явиться після запуску завдання.</p></details></article><form @submit.prevent="save"><fieldset :disabled="busy"><label class="toggle"><input type="checkbox" v-model="data.settings.enabled">Автоматичне резервне копіювання</label><div class="grid"><label>Періодичність<select v-model="data.settings.frequency"><option value="DAILY">Щодня</option><option value="WEEKLY">Щотижня</option></select></label><label v-if="data.settings.frequency==='WEEKLY'">День тижня<select v-model.number="data.settings.weekday"><option v-for="(day,i) in days" :key="i" :value="i+1">{{ day }}</option></select></label><label>Час за Києвом<input type="time" v-model="data.settings.time" required></label><label>Зберігати копій<input type="number" min="2" max="365" v-model.number="data.settings.keepCount" required></label></div><p>Планувальник перевіряє розклад кожні 15 хвилин. Старі копії переміщуються в кошик лише після успішної нової копії. Вимкнення розкладу не скасовує вже поставлені в чергу запити.</p><button class="primary">Зберегти налаштування</button></fieldset></form><div class="actions"><button :disabled="busy || data.runs.some(r => ['QUEUED','RUNNING'].includes(r.state))" @click="run">Створити копію зараз</button></div><h3>Останні 100 запусків</h3><p v-if="!data.runs.length">Копій ще немає.</p><article v-for="row in data.runs" :key="row.id" class="panel"><header><strong>{{ states[row.state] || row.state }}</strong><span>{{ date(row.createdAt) }}</span></header><p>{{ row.kind === 'MANUAL' ? 'Вручну: '+row.actor : 'За розкладом' }}<template v-if="row.bytes"> · {{ (Number(row.bytes)/1048576).toFixed(2) }} МБ</template></p><p v-if="row.message">{{ row.message }}</p><button v-if="row.state==='SUCCESS'" :disabled="busy" @click="download(row)">Завантажити на комп’ютер</button><details v-if="row.sha256"><summary>Перевірка файлу</summary><p>{{ row.fileName }}</p><code>SHA-256: {{ row.sha256 }}</code></details></article></template></section></template>
<style scoped>.backup{max-width:1040px}.backup header,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.backup h2{margin:0}.backup p{line-height:1.5}.panel{border:1px solid #dce4ec;border-radius:12px;padding:16px;margin:14px 0;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:14px;margin:16px 0}.grid label{display:grid;gap:6px;min-width:0}.grid input,.grid select{width:100%;min-width:0;box-sizing:border-box}fieldset{border:0;padding:0;min-width:0}.toggle{display:flex;gap:10px;align-items:center}.toggle input{width:20px;min-height:20px;flex:0 0 20px}.actions{margin-top:18px}summary{cursor:pointer}code{overflow-wrap:anywhere;white-space:normal}@media(max-width:520px){.grid{grid-template-columns:1fr}.backup header{align-items:flex-start}}</style>
